import java.util.Scanner;

public class OBADef {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long inputNumber = sc.nextLong();
        int digitCount = (int) (Math.log10(Math.abs(inputNumber)) + 1);
        System.out.println("" + computeCount(inputNumber, digitCount));
    }

    public static long buildOnes(long n) {
        return (long) (Math.pow(10, n) - 1) / 9;
    }

    public static long computeCount(long n, int length) {
        long ones = buildOnes(length);
        long total = (n / ones) * length;
        n %= ones;
        if (n == 0) return total;
        long option1 = (length + 1) + computeCount(ones - n, length - 1);
        long option2 = computeCount(n, length - 1);
        return total + Math.min(option1, option2);
    }
}
